specs=[
C('scale_equal_strips','Dải đỏ dài 7 cm. Dải xanh dài gấp 4 lần dải đỏ. Tìm chiều dài dải xanh.', [('Dải đỏ','7','cm'),('Số lần','4','lần')],'Tìm chiều dài dải xanh.',[S('Gấp chiều dài','Gấp bốn lần là ghép bốn phần bằng chiều dài dải đỏ.',28,'7+7+7+7=28; 28:4=7.','7*4','cm')],[('Dải xanh',28,'cm')]),
C('times_vs_add','Có 8 thẻ ban đầu. Phương án A tăng số thẻ lên gấp 3 lần; phương án B thêm 3 thẻ. Mỗi phương án bắt đầu riêng từ số ban đầu. Tính số thẻ theo từng phương án và so sánh.', [('Ban đầu','8','thẻ'),('Hệ số A','3','lần'),('Phần thêm B','3','thẻ')],'Tính và so sánh số thẻ hai phương án.',[S('Phương án A','Gấp lên nghĩa là lấy nhiều nhóm bằng lượng ban đầu.',24,'Ba nhóm tám thẻ có 24 thẻ; chia lại cho ba thu tám.','8*3','thẻ'),S('Phương án B','Thêm một số thẻ là cộng phần mới với phần cũ.',11,'11 bớt 3 còn8; không nhân vì đây là phần thêm.','8+3','thẻ'),S('So sánh','Hai phương án có cùng đơn vị.','A nhiều hơn B','So sánh24 với11; không thực hiện A rồi tiếp tục B trên cùng một chồng.')],[('Số thẻ A',24,'thẻ'),('Số thẻ B',11,'thẻ'),('So sánh','A nhiều hơn B','')]),
C('scale_down_stock','Một nhóm có 48 viên bi. Sau khi giảm số bi đi 6 lần, số bi còn bằng một trong các phần bằng nhau đó. Tìm số bi còn.', [('Ban đầu','48','viên'),('Giảm số lần','6','lần')],'Tìm số bi sau giảm theo số lần.',[S('Chia lượng ban đầu','Giảm đi sáu lần là chia lượng ban đầu thành sáu phần bằng nhau và lấy một phần.',8,'8*6=48, tái tạo số ban đầu.','48/6','viên')],[('Bi còn',8,'viên')]),
C('mis_subtract_times','Một đoạn dây dài 35 m cần giảm chiều dài đi 5 lần. Học sinh viết "35 - 5 = 30 m". Hãy sửa theo ý nghĩa giảm đi một số lần.', [('Chiều dài đầu','35','m'),('Số lần giảm','5','lần')],'Sửa phép tính và chiều dài sau giảm.',[S('Đối chiếu quan hệ','Đề nói giảm theo số lần; phép trừ trong câu viết chỉ bớt một độ dài cố định.','Cần chia theo số lần','Chỉ nhận xét phép trừ đã được viết, không suy ý nghĩ của học sinh.'),S('Tìm chiều dài','Chia chiều dài ban đầu thành năm phần bằng nhau, lấy một phần.',7,'7*5=35; 30*5 không tái tạo35.','35/5','m')],[('Chiều dài sau giảm',7,'m')],student='35 - 5 = 30 m',kind='misconception')]
